264	}
265	
266	// TestDelimiterIdentityDuplicateAcrossOrderAndEscapes：身份确实相同时，调换标签
267	// 书写顺序、用合法 JSON 转义书写同一个分隔字符，再次提交相同时间戳与数值都计为
268	// 重复，不新增点；成功结果里字符仍是解析后的真实文本（只有一个真实冒号）。
269	func TestDelimiterIdentityDuplicateAcrossOrderAndEscapes(t *testing.T) {
270		store := NewMetricStore()
271		mustOK(t, store, `[{"name":"m:x","timestamp":5,"value":4,"labels":{"a:1":"x;y","b":"{z}"}}]`)
272		// 标签顺序调换；名字里的冒号、键里的冒号、值里的分号与花括号改用 JSON
273		// #XX# 占位符对应的 \uXXXX 转义书写，解析后的真实文本必须与首条完全一致。
274		resubmit := withJSONEscapes(
275			`[{"name":"m#CO#x","timestamp":5,"value":4.0,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
276		res := mustOK(t, store, resubmit)
277		if res.Added != 0 || res.Duplicates != 1 || len(res.Series) != 1 {
278			t.Fatalf("escaped/reordered resubmit must be one duplicate, got %+v", res)
279		}
280		got := res.Series[0]
281		wantLabels := map[string]string{"a:1": "x;y", "b": "{z}"}
282		if got.Name != "m:x" || !reflect.DeepEqual(got.Labels, wantLabels) {
283			t.Fatalf("identity must resolve to parsed text, got name=%q labels=%v", got.Name, got.Labels)
284		}
285		if pts := got.Points; len(pts) != 1 || pts[0] != (Point{Timestamp: 5, Value: 4}) {
286			t.Fatalf("duplicate must add no point, got %+v", pts)
287		}
288	
289		// 同一时间戳换成不同数值（同样以转义+乱序书写身份）：拒绝整批，冲突指向
290		// JSON 解析后的真实完整序列、时间戳以及已有值与提交值。
291		conflictLine := withJSONEscapes(
292			`[{"name":"m#CO#x","timestamp":5,"value":40,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
293		lerr := mustFail(t, store, conflictLine)
294		if lerr.Index != 1 || lerr.Conflict == nil {
295			t.Fatalf("expected conflict, got %+v", lerr)
296		}
297		c := lerr.Conflict
298		if c.Series.Name != "m:x" || !reflect.DeepEqual(c.Series.Labels, wantLabels) ||
299			c.Timestamp != 5 || c.Existing != 4 || c.Submitted != 40 {
300			t.Fatalf("conflict must name real identity/values, got %+v", c)
301		}
302		// 冲突原因文本里的序列按 name{k=v,...} 呈现；该表示对含分隔字符的数据有歧义
303		// （单标签 a=b=2 与两标签 a=1,b=2 的渲染相同），因此冲突的权威归属以结构化
304		// conflict.series 为准。这里锁定现有文本格式不被意外改动。
305		if !strings.HasPrefix(lerr.Error, "conflict: series m:x{a:1=x;y,b={z}} at timestamp 5 already has value 4, submitted 40") {
306			t.Fatalf("conflict message = %q", lerr.Error)
307		}
308		// 原采样点保持不变。
309		snap := mustOK(t, store, `[]`)
310		if pts := snap.Series[0].Points; len(pts) != 1 || pts[0].Value != 4 {
311			t.Fatalf("rejected batch must leave original point intact, got %+v", pts)
312		}
313	}
314	
315	// TestLookAlikeIdentitiesDoNotConflict：两条文本渲染完全相同的不同序列，在同一
316	// 时间戳分别提交不同数值不得互相冲突；随后对其中一条再改值才冲突，且冲突报告的
317	// 是结构化的真实完整标签集合，而不是有歧义的渲染文本。
318	func TestLookAlikeIdentitiesDoNotConflict(t *testing.T) {
319		store := NewMetricStore()
320		mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":1,"labels":{"a":"b=2"}}]`)
321		// 单标签 a="b=2" 与两标签 a=1,b=2 的 String() 都是 cpu{a=b=2}，但身份不同。
322		res := mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":2,"labels":{"a":"1","b":"2"}}]`)
323		if res.Added != 1 || res.Duplicates != 0 || len(res.Series) != 2 {
324			t.Fatalf("look-alike identities with different values must both be added, got %+v", res)
325		}
326		// 对单标签序列提交不同值：冲突，结构化标签只有一个键且值原样为 "b=2"。
327		lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"b=2"}}]`)
328		if lerr.Conflict == nil || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 9 {
329			t.Fatalf("single-label conflict values wrong: %+v", lerr.Conflict)
330		}
331		if labels := lerr.Conflict.Series.Labels; len(labels) != 1 || labels["a"] != "b=2" {
332			t.Fatalf("conflict must name real single-label identity, got %v", labels)
333		}
334		// 对两标签序列提交不同值同样冲突，结构化标签是两个键。
335		lerr = mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"1","b":"2"}}]`)
336		if lerr.Conflict == nil || lerr.Conflict.Existing != 2 {
337			t.Fatalf("two-label conflict values wrong: %+v", lerr.Conflict)
338		}
339		if labels := lerr.Conflict.Series.Labels; len(labels) != 2 || labels["a"] != "1" || labels["b"] != "2" {
340			t.Fatalf("conflict must name real two-label identity, got %v", labels)
341		}
342		// 两条序列原有采样点都保持各自的值，全量查询仍返回两条独立序列。
343		full := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":10}`)
344		if len(full.Series) != 2 {
345			t.Fatalf("full cpu query = %+v, want 2 series", full.Series)
346		}
347		for _, s := range full.Series {
348			if s.Count != 1 {
349				t.Fatalf("series %v must keep its own point, got count=%d", s.Labels, s.Count)
350			}
351		}
352	}
353	
354	// TestWhitespaceInIdentityPreservedVerbatim：名称、标签键和值中的合法空格原样
355	// 保留，不能通过去空格把不同输入合并为同一序列。
356	func TestWhitespaceInIdentityPreservedVerbatim(t *testing.T) {
357		store := NewMetricStore()
358		res := mustOK(t, store, `[
359			{"name":"m ","timestamp":1,"value":1,"labels":{"k ":"v"}},
360			{"name":"m","timestamp":1,"value":2,"labels":{"k":"v"}},
361			{"name":"m","timestamp":1,"value":3,"labels":{"k":" v"}},
362			{"name":"m","timestamp":1,"value":4,"labels":{"k":"v "}},
363			{"name":"m","timestamp":1,"value":5,"labels":{" k":"v"}}
364		]`)
365		if res.Added != 5 || len(res.Series) != 5 {
366			t.Fatalf("whitespace variants must be 5 distinct series, got added=%d series=%d", res.Added, len(res.Series))
367		}
368		cases := []struct {
369			name   string
370			labels map[string]string
371			value  float64
372		}{
373			{"m ", map[string]string{"k ": "v"}, 1},
374			{"m", map[string]string{"k": "v"}, 2},
375			{"m", map[string]string{"k": " v"}, 3},
376			{"m", map[string]string{"k": "v "}, 4},
377			{"m", map[string]string{" k": "v"}, 5},
378		}
379		for i, c := range cases {
380			var line string
381			if c.name == "m" {
382				line = queryLabels("m", 0, 10, c.labels)
383			} else {
384				line = `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":10,"labels":` + jsonLabels(c.labels) + `}`
385			}
386			got := queryOne(t, store, line)
387			if got.Name != c.name || !reflect.DeepEqual(got.Labels, c.labels) || got.Average != c.value {
388				t.Fatalf("whitespace case %d: got %+v, want name=%q labels=%v value=%v", i, got, c.name, c.labels, c.value)
389			}
390		}
391		// 省略标签与空标签对象同一身份；缺标签与标签存在且值为空串仍是不同身份，
392		// 即使标签键周围带有合法空格。
393		mustOK(t, store, `[{"name":"n","timestamp":1,"value":1}]`)
394		if dup := mustOK(t, store, `[{"name":"n","timestamp":1,"value":1.0,"labels":{}}]`); dup.Added != 0 || dup.Duplicates != 1 {
395			t.Fatalf("omitted vs empty labels must be the same series, got %+v", dup)
396		}
397		if added := mustOK(t, store, `[{"name":"n","timestamp":1,"value":2,"labels":{" z ":""}}]`); added.Added != 1 {
398			t.Fatalf("missing label differs from present empty value, added = %d", added.Added)
399		}
400		// 快照中 n 现在有两条独立序列：无标签与带空值标签（连同 m 的五条共七条）。
401		nSeries := 0
402		for _, v := range mustOK(t, store, `[]`).Series {
403			if v.Name == "n" {
404				nSeries++
405			}
406		}
407		if nSeries != 2 {
408			t.Fatalf("metric n must have 2 distinct series, got %d", nSeries)
409		}
410		got := queryOne(t, store, queryLabels("n", 0, 10, map[string]string{" z ": ""}))
411		if len(got.Labels) != 1 || got.Labels[" z "] != "" || got.Average != 2 {
412			t.Fatalf("spaced-key empty-value label not preserved: %+v", got)
413		}
414	}
415	
416	// TestDelimiterLabelSubsetMatching：子集匹配按真实键值对进行，值里的分隔符既不会
417	// 制造额外的匹配标签，也不会让需要的标签匹配失败；不同序列的点不混合。
418	func TestDelimiterLabelSubsetMatching(t *testing.T) {
419		store := NewMetricStore()
420		mustOK(t, store, `[
421			{"name":"m","timestamp":1,"value":10,"labels":{"a":"x","b":"y=z"}},
422			{"name":"m","timestamp":1,"value":20,"labels":{"a":"x","b":"q"}},
423			{"name":"m","timestamp":1,"value":30,"labels":{"a":"x","b":"y=z","c":"d,e"}}
424		]`)
425		// a=x 子集命中三条，各自独立返回自己的点与均值。
426		res := mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"a": "x"}))
427		if len(res.Series) != 3 {
428			t.Fatalf("a=x subset = %+v, want 3 series", res.Series)
429		}
430		// b="y=z" 只命中真实拥有该键值的两条（含带额外标签 c 的一条），不命中 b=q。
431		res = mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"b": "y=z"}))
432		if len(res.Series) != 2 {
433			t.Fatalf("b=y=z subset = %+v, want 2 series", res.Series)
434		}
435		wantAvgs := map[int]bool{10: false, 30: false}
436		for _, s := range res.Series {
437			if s.Count != 1 {
438				t.Fatalf("matched series %v must report its own single point, got count=%d", s.Labels, s.Count)
439			}
440			if _, ok := wantAvgs[int(s.Average)]; !ok {
441				t.Fatalf("unexpected average %v from %v", s.Average, s.Labels)
442			}
443			wantAvgs[int(s.Average)] = true
444		}
445		for v, seen := range wantAvgs {
446			if !seen {
447				t.Fatalf("series with average %d was not matched separately", v)
448			}
449		}
450		// 查询值里写逗号文本是完整值比较：只有值恰好为 "d,e" 的标签能匹配。
451		if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"c": "d,e"})); got.Average != 30 {
452			t.Fatalf("comma-in-value subset = %+v, want average 30", got)
453		}
454		if len(mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"d": "e"})).Series) != 0 {
455			t.Fatalf("value fragment d,e must not be split into label d=e")
456		}
457	}
