		t.Fatalf("line 2 series count = %d, want 5", n)
	}
	// 转义书写解析回真实冒号/分号后仍只匹配原来那一条。
	findWireSeries(t, second["series"].([]interface{}), "cpu", map[string]interface{}{"a:b": "c;d"})

	// 行 3：整批失败，结构化冲突指出真实完整序列、时间戳与两个数值。
